PRAGMA foreign_keys = ON;
DROP TABLE IF EXISTS reviews_w6d4;
DROP TABLE IF EXISTS games_w6d4;
DROP TABLE IF EXISTS operators_w6d4;
CREATE TABLE operators_w6d4(operator_id INTEGER PRIMARY KEY,operator_name TEXT NOT NULL,team TEXT NOT NULL);
CREATE TABLE games_w6d4(game_id INTEGER PRIMARY KEY,game_date TEXT NOT NULL,league TEXT NOT NULL,operator_id INTEGER NOT NULL,game_status TEXT NOT NULL,FOREIGN KEY(operator_id) REFERENCES operators_w6d4(operator_id));
CREATE TABLE reviews_w6d4(review_id INTEGER PRIMARY KEY,game_id INTEGER NOT NULL,review_type TEXT NOT NULL,priority TEXT NOT NULL,completed INTEGER NOT NULL,within_sla INTEGER,FOREIGN KEY(game_id) REFERENCES games_w6d4(game_id));
